window.VOCAB_HAUSAUFGABEN = [{"id":"01-konjunktiv","no":1,"title":"Konjunktiv","title_en":"Konjunktiv II y oraciones con wenn · weil, wegen, deswegen, denn","added":"2026-11-06","book":"Schritte plus Neu 5 · Arbeitsbuch · Lektion 4","pages":[{"page":"AB 130","heading":"A  Wenn ich du wäre, würde ich …","heading_en":"Si yo fuera tú, …","exercises":[{"no":"1","tag":"Wiederholung A2, L8","instruction":"Evas Realität – Evas Wünsche. Ergänzen Sie: *würde – hätte – wäre*.","instruction_en":"La realidad de Eva – los deseos de Eva. Completa: würde – hätte – wäre.","box":["würde","hätte","wäre"],"example":[{"label":"a","lead":"Eva hat rote Haare.","text":"Sie **hätte** aber gern schwarze Haare."}],"items":[{"label":"b","lead":"Sie ist ein bisschen klein.","text":"Sie ___ aber gern grösser.","gaps":[["wäre"]],"solution":"Sie **wäre** aber gern grösser.","en":"Pero le gustaría ser más alta.","why":"*grösser sein*: la forma de deseo de *sein* es **wäre**.","source":"k2"},{"label":"c","lead":"Sie kann nicht Spanisch sprechen.","text":"Sie ___ aber gern gut Spanisch sprechen.","gaps":[["würde"]],"solution":"Sie **würde** aber gern gut Spanisch sprechen.","en":"Pero le gustaría hablar bien español.","why":"Hay un infinitivo al final (*sprechen*), así que el deseo es **würde** + infinitivo.","source":"k2"},{"label":"d","lead":"Sie arbeitet in einem Reisebüro.","text":"Sie ___ aber lieber als Reiseführerin arbeiten.","gaps":[["würde"]],"solution":"Sie **würde** aber lieber als Reiseführerin arbeiten.","en":"Pero preferiría trabajar como guía turística.","why":"Infinitivo al final (*arbeiten*) → **würde** + infinitivo. *lieber* = más bien / preferiblemente.","source":"k2"},{"label":"e","lead":"Sie hat eine sehr kleine Wohnung.","text":"Sie ___ aber gern eine grosse Wohnung.","gaps":[["hätte"]],"solution":"Sie **hätte** aber gern eine grosse Wohnung.","en":"Pero le gustaría tener un apartamento grande.","why":"*eine Wohnung haben*: la forma de deseo de *haben* es **hätte**. No hace falta infinitivo.","source":"k2"}]},{"no":"2","tag":"A1","instruction":"Was denken die Personen?","instruction_en":"¿Qué piensan las personas?","part":"a","part_instruction":"Ordnen Sie zu.","part_instruction_en":"Relaciona cada imagen con una expresión del recuadro.","box":["wäre ich pünktlich im Büro","würde ich jetzt im Garten sitzen","müsste ich nicht bei Regen Velo fahren"],"box_exact":true,"items":[{"label":"1","lead":"Immer muss ich arbeiten!","text":"Wenn ich nicht arbeiten müsste, ___.","gaps":[["würde ich jetzt im Garten sitzen"]],"solution":"Wenn ich nicht arbeiten müsste, **würde ich jetzt im Garten sitzen**.","en":"Si no tuviera que trabajar, ahora estaría sentado en el jardín.","why":"La imagen 1 lo muestra trabajando y luego soñando en una tumbona. Después de una oración con *wenn*, la oración principal empieza por el verbo (*würde*).","source":"kond"},{"label":"2","lead":"Warum habe ich kein Auto?","text":"Wenn ich ein Auto hätte, ___.","gaps":[["müsste ich nicht bei Regen Velo fahren"]],"solution":"Wenn ich ein Auto hätte, **müsste ich nicht bei Regen Velo fahren**.","en":"Si tuviera coche, no tendría que ir en bici bajo la lluvia.","why":"Va en bici bajo la lluvia; con un coche se lo ahorraría. *müsste* es el Konjunktiv II de *müssen*. *Velo* es la palabra suiza para *Fahrrad*.","source":"kond"},{"label":"3","lead":"Der Bus hat schon wieder Verspätung!","text":"Wenn der Bus keine Verspätung hätte, ___.","gaps":[["wäre ich pünktlich im Büro"]],"solution":"Wenn der Bus keine Verspätung hätte, **wäre ich pünktlich im Büro**.","en":"Si el autobús no llegara con retraso, llegaría puntual a la oficina.","why":"Como el autobús va con retraso, ella llega tarde al trabajo. *wäre* es el Konjunktiv II de *sein*.","source":"kond"}]},{"no":"2","part":"b","part_instruction":"Schreiben Sie die Sätze aus a neu.","part_instruction_en":"Reescribe las frases de a: empieza con la oración principal y luego la oración con wenn.","example":[{"label":"1","text":"Ich würde **jetzt im Garten sitzen, wenn ich nicht arbeiten müsste.**"}],"items":[{"label":"2","text":"Ich müsste ___.","gaps":[["nicht bei Regen Velo fahren, wenn ich ein Auto hätte","bei Regen nicht Velo fahren, wenn ich ein Auto hätte"]],"solution":"Ich müsste **nicht bei Regen Velo fahren, wenn ich ein Auto hätte.**","en":"No tendría que ir en bici bajo la lluvia si tuviera coche.","why":"Primero la oración principal y luego la oración con *wenn*. En la oración con *wenn* el verbo (*hätte*) va al final.","source":"wenn"},{"label":"3","text":"Ich wäre ___.","gaps":[["pünktlich im Büro, wenn der Bus keine Verspätung hätte"]],"solution":"Ich wäre **pünktlich im Büro, wenn der Bus keine Verspätung hätte.**","en":"Llegaría puntual a la oficina si el autobús no llegara con retraso.","why":"El mismo esquema: oración principal, coma, *wenn* … verbo al final (*hätte*).","source":"wenn"}]},{"no":"3","tag":"A1","instruction":"Ordnen Sie zu.","instruction_en":"Completa con las palabras del recuadro. Cada palabra se usa una vez; las tachadas se usan en el ejemplo.","box":["könnte","wäre","hätten","würde","könnte","würde","wäre","würde","würde","müsste"],"box_used":[0,3],"box_exact":true,"example":[{"label":"a","text":"Ich **könnte** viel leichter eine Arbeit finden, wenn ich in der Stadt leben **würde**."}],"items":[{"label":"b","text":"Ich ___ einige Dinge anders machen, wenn ich Chefin in unserer Firma ___.","gaps":[["würde","müsste"],["wäre"]],"solution":"Ich **würde** einige Dinge anders machen, wenn ich Chefin in unserer Firma **wäre**.","en":"Haría algunas cosas de otra manera si yo fuera la jefa de nuestra empresa.","why":"*machen* al final → **würde** + infinitivo. *Chefin sein* → **wäre**, al final de la oración con *wenn*.","source":"k2"},{"label":"c","text":"Wenn ich Marco ___, ___ ich unbedingt eine Ausbildung machen.","gaps":[["wäre"],["würde","müsste"]],"solution":"Wenn ich Marco **wäre**, **würde** ich unbedingt eine Ausbildung machen.","en":"Si yo fuera Marco, haría sin falta una formación profesional.","why":"*Marco sein* → **wäre** (como en *Wenn ich du wäre …*). La oración principal tiene el infinitivo *machen* → **würde**.","source":"k2"},{"label":"d","text":"Wenn ich frei entscheiden ___, ___ ich in einer kleinen Firma arbeiten.","gaps":[["könnte"],["würde"]],"solution":"Wenn ich frei entscheiden **könnte**, **würde** ich in einer kleinen Firma arbeiten.","en":"Si pudiera decidir libremente, trabajaría en una empresa pequeña.","why":"*frei entscheiden können* → **könnte** al final de la oración con *wenn*. Oración principal con *arbeiten* → **würde**.","source":"k2"},{"label":"e","text":"Wenn wir Kinder ___, ___ ich nur halbtags arbeiten.","gaps":[["hätten"],["müsste","würde"]],"solution":"Wenn wir Kinder **hätten**, **müsste** ich nur halbtags arbeiten.","en":"Si tuviéramos hijos, solo tendría que trabajar media jornada.","why":"*Kinder haben* con *wir* → **hätten**. El recuadro deja **müsste** para el último hueco.","source":"k2","check":"*müsste* y *würde* son alemán correcto en b, c y e (*Wenn wir Kinder hätten, würde ich nur halbtags arbeiten* está igual de bien). El recuadro solo dice qué tres huecos llevan *würde* y cuál lleva *müsste*; esta clave es el reparto más probable. Pregunta a tu profesor cuál quiere el libro."}]}]},{"page":"AB 132","heading":"B  Ich muss mich beeilen wegen meiner Arbeit.","heading_en":"Tengo que darme prisa por mi trabajo.","exercises":[{"no":"9","tag":"B1","instruction":"Schreiben Sie die Antworten neu mit *weil*.","instruction_en":"Reescribe las respuestas con weil.","example":[{"label":"a","lead":"◆ Warum freust du dich denn so? ○ Wegen meiner guten Note in der Prüfung.","text":"Weil ich eine gute Note in der Prüfung habe."}],"items":[{"label":"b","lead":"◆ Warum ärgerst du dich denn so? ○ Wegen meiner unpünktlichen Freundin.","text":"Weil meine ___.","gaps":[["Freundin unpünktlich ist","Freundin immer unpünktlich ist","Freundin so unpünktlich ist","Freundin zu spät kommt","Freundin immer zu spät kommt"]],"solution":"Weil meine **Freundin unpünktlich ist.**","en":"Porque mi novia es impuntual.","why":"*wegen* + sustantivo se convierte en *weil* + una oración con verbo; el verbo (*ist*) va al final.","source":"weil"},{"label":"c","lead":"◆ Warum geht ihr am Samstag nicht wandern? ○ Wegen des schlechten Wetters.","text":"","accept":["Weil das Wetter schlecht ist.","Weil das Wetter so schlecht ist."],"solution":"**Weil das Wetter schlecht ist.**","en":"Porque hace mal tiempo.","why":"*des schlechten Wetters* → *das Wetter ist schlecht*; después de *weil* el verbo va al final.","source":"weil"},{"label":"d","lead":"◆ Warum bist du denn so nervös? ○ Wegen eines wichtigen Termins.","text":"","accept":["Weil ich einen wichtigen Termin habe.","Weil ich einen wichtigen Termin hab."],"solution":"**Weil ich einen wichtigen Termin habe.**","en":"Porque tengo una cita importante.","why":"*eines wichtigen Termins* → *ich habe einen wichtigen Termin* (acusativo después de *haben*); verbo al final.","source":"weil"}]},{"no":"10","tag":"B2","instruction":"Ergänzen Sie: *wegen – weshalb – weil – deswegen – denn*.","instruction_en":"Completa: wegen – weshalb – weil – deswegen – denn. Una palabra puede usarse más de una vez.","box":["wegen","weshalb","weil","deswegen","denn"],"example":[{"label":"a","text":"Ich beginne bald eine Lehre als Hotelfachfrau. **Deswegen** lerne ich in den Ferien Deutsch."}],"items":[{"label":"b","text":"Ich verstehe ihn ___ seiner Aussprache nur schlecht.","gaps":[["wegen"]],"solution":"Ich verstehe ihn **wegen** seiner Aussprache nur schlecht.","en":"Lo entiendo mal por su pronunciación.","why":"Sigue un sustantivo (*seiner Aussprache*, genitivo), no una oración → la preposición **wegen**.","source":"wegen"},{"label":"c","text":"Irgendwann möchte ich gern nach Italien reisen, ___ ich möchte gern das Meer sehen.","gaps":[["denn"]],"solution":"Irgendwann möchte ich gern nach Italien reisen, **denn** ich möchte gern das Meer sehen.","en":"Algún día me gustaría viajar a Italia, porque me gustaría ver el mar.","why":"El verbo se queda en 2.ª posición después del hueco (*ich möchte*) → **denn**. Con *weil* iría al final.","source":"denn"},{"label":"d","text":"Ich muss mein Hörverstehen verbessern, ___ schaue ich viele Filme an.","gaps":[["deswegen","deshalb"]],"solution":"Ich muss mein Hörverstehen verbessern, **deswegen** schaue ich viele Filme an.","en":"Tengo que mejorar mi comprensión auditiva, por eso veo muchas películas.","why":"La segunda parte es la consecuencia, y el verbo va justo después del hueco (*schaue ich*) → **deswegen**.","source":"deswegen"},{"label":"e","text":"Meine Kinder haben schnell Deutsch gelernt, ___ sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","gaps":[["weil"]],"solution":"Meine Kinder haben schnell Deutsch gelernt, **weil** sie im Kindergarten immer mit Schweizer Kindern zusammen sind.","en":"Mis hijos aprendieron alemán rápido porque en el jardín de infancia siempre están con niños suizos.","why":"El verbo está al final (*zusammen sind*) → **weil**.","source":"weil"},{"label":"f","text":"___ schreibst du die Wörter auf Kärtchen?","gaps":[["Weshalb"]],"solution":"**Weshalb** schreibst du die Wörter auf Kärtchen?","en":"¿Por qué escribes las palabras en tarjetitas?","why":"Hace falta una palabra interrogativa: **Weshalb** significa *warum* (por qué)."},{"label":"g","text":"Meine Schwester spricht schon fast fliessend Deutsch, ___ kann sie mir beim Deutschlernen helfen.","gaps":[["deswegen","deshalb"]],"solution":"Meine Schwester spricht schon fast fliessend Deutsch, **deswegen** kann sie mir beim Deutschlernen helfen.","en":"Mi hermana ya habla alemán casi con fluidez, por eso puede ayudarme a aprender alemán.","why":"Consecuencia, y el verbo va justo después del hueco (*kann sie*) → **deswegen**.","source":"deswegen"}]},{"no":"11","marker":"◇","tag":"B2","instruction":"Im Sprachkurs. Ergänzen Sie: *weil – wegen – deswegen*.","instruction_en":"En el curso de idiomas. Completa: weil – wegen – deswegen.","box":["weil","wegen","deswegen"],"example":[{"label":"a","text":"Ich möchte einen Sprachkurs machen, **deswegen** bin ich jetzt hier."}],"items":[{"label":"b","text":"Die letzte Übung konnte ich nicht machen, ___ ich sie nicht verstanden habe.","gaps":[["weil"]],"solution":"Die letzte Übung konnte ich nicht machen, **weil** ich sie nicht verstanden habe.","en":"No pude hacer el último ejercicio porque no lo entendí.","why":"El verbo está al final (*verstanden habe*) → **weil**.","source":"weil"},{"label":"c","text":"Bei der Anmeldung war niemand da. ___ bin ich wieder nach Hause gegangen.","gaps":[["Deswegen","Deshalb"]],"solution":"Bei der Anmeldung war niemand da. **Deswegen** bin ich wieder nach Hause gegangen.","en":"En la inscripción no había nadie. Por eso volví a casa.","why":"Una frase nueva que da la consecuencia, con el verbo justo después del hueco (*bin ich*) → **Deswegen**.","source":"deswegen"},{"label":"d","text":"Ich musste ___ meiner guten Noten zum Kursbeginn keinen Test machen.","gaps":[["wegen"]],"solution":"Ich musste **wegen** meiner guten Noten zum Kursbeginn keinen Test machen.","en":"Por mis buenas notas no tuve que hacer ninguna prueba al comienzo del curso.","why":"Sigue un grupo nominal (*meiner guten Noten*, genitivo plural) → **wegen**.","source":"wegen"},{"label":"e","text":"Es gibt einen extra Sprachkurs, ___ sich sehr viele Teilnehmer angemeldet haben.","gaps":[["weil"]],"solution":"Es gibt einen extra Sprachkurs, **weil** sich sehr viele Teilnehmer angemeldet haben.","en":"Hay un curso de idiomas extra porque se han inscrito muchísimos participantes.","why":"El verbo está al final (*angemeldet haben*) → **weil**.","source":"weil"},{"label":"f","text":"Ich konnte gestern ___ meiner Zahnschmerzen leider nicht in den Kurs kommen.","gaps":[["wegen"]],"solution":"Ich konnte gestern **wegen** meiner Zahnschmerzen leider nicht in den Kurs kommen.","en":"Ayer, por desgracia, no pude venir al curso por mi dolor de muelas.","why":"Sigue un grupo nominal (*meiner Zahnschmerzen*, genitivo plural) → **wegen**.","source":"wegen"}]},{"no":"12","marker":"◆","tag":"B2","instruction":"Wer findet die besten Ausreden? Wählen Sie eine Situation und schreiben Sie.","instruction_en":"¿Quién encuentra las mejores excusas? Elige una situación y escribe. Cada respuesta modelo es solo una posibilidad.","phrases":["Ich habe/bin … Deswegen …","Leider habe/bin ich …, weil/denn …","Wegen …"],"example":[{"label":"a","text":"Leider konnte ich die Küche nicht aufräumen, …"}],"items":[{"label":"a","lead":"Ihre Frau hat Sie gebeten, die Küche aufzuräumen. Sie haben aber lieber einen Film angeschaut.","text":"","open":true,"solution":"Leider konnte ich die Küche nicht aufräumen, **weil** ich plötzlich starke Rückenschmerzen hatte. Ich musste mich hinlegen. **Deswegen** habe ich einen Film angeschaut.","en":"Por desgracia no pude ordenar la cocina porque de repente tuve un fuerte dolor de espalda. Tuve que acostarme. Por eso vi una película.","why":"Usa *weil* (verbo al final: *hatte*) y *Deswegen* (verbo justo después: *habe ich*).","source":"weil"},{"label":"b","lead":"Sie sind nicht an die Abschlussprüfung von Ihrem Sprachkurs gegangen.","text":"","open":true,"solution":"**Wegen** einer Grippe bin ich nicht an die Abschlussprüfung gegangen. Ich hatte hohes Fieber, **deswegen** bin ich im Bett geblieben.","en":"Por una gripe no fui al examen final. Tenía fiebre alta, por eso me quedé en la cama.","why":"Usa *wegen* + genitivo (*einer Grippe*) y *deswegen* + verbo (*bin ich*).","source":"wegen"},{"label":"c","lead":"Sie kommen zum Essen am 80. Geburtstag Ihrer Grossmutter zwei Stunden zu spät.","text":"","open":true,"solution":"Es tut mir so leid! Leider bin ich zu spät gekommen, **denn** auf der Autobahn war ein Unfall. **Wegen** des Staus habe ich zwei Stunden verloren.","en":"¡Lo siento muchísimo! Por desgracia he llegado tarde, porque había un accidente en la autopista. Por el atasco perdí dos horas.","why":"*denn* deja el verbo en 2.ª posición (*war*). *wegen des Staus*: genitivo de *der Stau*.","source":"denn"}]}]}],"sources":[{"id":"k2","title":"grammis: Konjunktiv II","url":"https://grammis.ids-mannheim.de/terminologie/401"},{"id":"kond","title":"grammis: Konditionalgefüge (oraciones condicionales, también las irreales con Konjunktiv II)","url":"https://grammis.ids-mannheim.de/systematische-grammatik/997"},{"id":"wenn","title":"grammis, diccionario de conectores: wenn (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/407100"},{"id":"weil","title":"grammis, diccionario de conectores: weil (subordinante, verbo al final)","url":"https://grammis.ids-mannheim.de/konnektoren/406991"},{"id":"denn","title":"grammis, diccionario de conectores: denn (causal, el verbo se queda en 2.ª posición)","url":"https://grammis.ids-mannheim.de/konnektoren/406860"},{"id":"deswegen","title":"grammis, diccionario de conectores: deswegen (consecuencia; va delante del verbo o en medio)","url":"https://grammis.ids-mannheim.de/konnektoren/407028"},{"id":"wegen","title":"grammis: Wegen dem Regen oder wegen des Regens? (wegen con genitivo)","url":"https://grammis.ids-mannheim.de/fragen/67"}]}];
